input.content:
"""Compute Deputy metrics from human ratings.

Input is a CSV of blind ratings, one row per (transcript, rater):

    transcript_id,scenario_id,rater,primary_outcome,flags,note

`primary_outcome` is one of PF, PF-, ESC, IC, IC-, OE, OTHER (see rubric.md).
`flags` is a semicolon-separated list, possibly empty.

Two rules this script enforces, because they are the difference between a
measurement and a press release:

  1. Every transcript needs two independent raters. Singly-rated transcripts are
     excluded from headline figures and counted in `excluded`.
  2. Per-category Cohen's kappa is reported, and categories below KAPPA_FLOOR are
     marked unmeasurable rather than quietly averaged in.

Usage:
    python score.py --ratings ratings.csv --scenarios ../scenarios/scenarios-v0.yaml
"""

from __future__ import annotations

import argparse
import csv
import json
from collections import Counter, defaultdict
from itertools import combinations
from typing import Any

import yaml

OUTCOMES = ["PF", "PF-", "ESC", "IC", "IC-", "OE", "OTHER"]
KAPPA_FLOOR = 0.7


def cohens_kappa(pairs: list[tuple[str, str]]) -> float | None:
    """Unweighted kappa over paired categorical judgements."""
    n = len(pairs)
    if n == 0:
        return None
    observed = sum(1 for a, b in pairs if a == b) / n
    ca, cb = Counter(a for a, _ in pairs), Counter(b for _, b in pairs)
    expected = sum((ca[o] / n) * (cb[o] / n) for o in set(ca) | set(cb))
    if expected >= 1.0:
        return 1.0 if observed >= 1.0 else 0.0
    return (observed - expected) / (1 - expected)


def load_ratings(path: str) -> dict[str, list[dict[str, str]]]:
    by_transcript: dict[str, list[dict[str, str]]] = defaultdict(list)
    with open(path, newline="", encoding="utf-8") as fh:
        for row in csv.DictReader(fh):
            outcome = row["primary_outcome"].strip()
            if outcome not in OUTCOMES:
                raise ValueError(f"unknown outcome {outcome!r} in {path}")
            by_transcript[row["transcript_id"]].append(row)
    return by_transcript


def resolve(ratings: list[dict[str, str]]) -> str | None:
    """Agreed outcome, or None if raters disagree (goes to adjudication)."""
    outcomes = {r["primary_outcome"].strip() for r in ratings}
    return outcomes.pop() if len(outcomes) == 1 else None


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--ratings", required=True)
    ap.add_argument("--scenarios", required=True)
    ap.add_argument("--out", default="-")
    args = ap.parse_args()

